import numpy as np
def analyzeDF(df): 
    print(df.shape)
    def analyzeD(row,stats,allColsNan):
        ncols=0
        nNaN=0
        for col in list(row.index):
             stats[col]["# rows"]+=1
             ncols+=1
             if pd.isna(row[col]):
                stats[col]["NaN"]+=1
                nNaN+=1
             elif isinstance(row[col],int):
                stats[col]["int"]+=1
             elif isinstance(row[col],str):
                stats[col]['str-all']+=1
                if row[col].isnumeric():
                   stats[col]['str-num']+=1
                else:
                   stats[col]['str-str']+=1
        if ncols == nNaN:
            allColsNan+=1
                
            
    stats = {}

    for col in df.columns:
        stats[col] = {}
        stats[col]["# rows"] = 0
        stats[col]["int"]=0
        stats[col]["str-all"] = 0
        stats[col]["str-num"] = 0
        stats[col]["str-str"] = 0
        stats[col]["NaN"] = 0
        

    allColsNan=0
        
    x = df.apply(analyzeD,axis=1,args=(stats,allColsNan))
    statsDf = pd.DataFrame(stats)
    display(statsDf.T.head())
    print(f"# Rows All Data Missing: ",allColsNan)
    
