def invYrMo(df,colDate,formt,type=0):
    print("TYpe ",type)
    import pandas as pd
    # type = 0: simple inventory
    #            1: creeate year-month-day inventory
    #           2: create year-month inventory
    mons = ["","Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Dec"]
    if type == 0:  # simple, quick format 
        a = df.copy()
        a["jlcDateInv"] = pd.to_datetime(a[colDate],format=formt)
        a["jlcYear"] = a["jlcDateInv"].dt.year
        a["jlcMonth"] = a["jlcDateInv"].dt.month
        inv = a.groupby(["jlcYear","jlcMonth"]).count()    
    elif type == 1:  # year-month-day, with year and month as columns and thne each day as column w/ a count
        stats = {}
        a = df.copy()
        a["jlcDateInv"] = pd.to_datetime(a[colDate],format=formt)
        a["jlcYear"] = a["jlcDateInv"].dt.year
        a["jlcMonth"] = a["jlcDateInv"].dt.month
        a["jlcDay"] = a["jlcDateInv"].dt.day
        b = a.groupby(["jlcYear","jlcMonth","jlcDay"],as_index=False).count()
        for yr in range(b["jlcYear"].min(),b["jlcYear"].max()+1):
            stats[yr] = {}
            monthLast = 12
            if yr == pd.Timestamp.today().year:
                monthLast = pd.Timestamp.today().month
            for mo in range(1,monthLast+1):
               stats[yr][mo] = {}
               for dy in range(1,32):
                stats[yr][mo][dy]=0

        for indx,row in b.iterrows():
            yr = row["jlcYear"]
            mo = row["jlcMonth"]
            dy = row["jlcDay"]
            cnt = row[colDate]
            stats[yr][mo][dy]=cnt

        nrec=0
        for yr in range(b["jlcYear"].min(),b["jlcYear"].max()+1):
             print(yr)
             monthLast = 12
             if yr == pd.Timestamp.today().year:
                monthLast = pd.Timestamp.today().month
             for mo in range(1,monthLast+1):
                lu = {f"Day {nn}":[stats[yr][mo][nn]] for nn in range(1,32)}
                l = {"year":[yr],"month":[mo]}
                l.update(lu)
                tmp = pd.DataFrame(l)
                nrec+=1
                if nrec > 1:
                   inv = pd.concat([inv,tmp])
                else:
                   inv = tmp
                
    elif type == 2:  # year-month
        print("Starting")
        stats = {}
        a = df.copy()
        a["jlcDateInv"] = pd.to_datetime(df[colDate],format=formt)
        a["jlcYear"] = a["jlcDateInv"].dt.year
        a["jlcMonth"] = a["jlcDateInv"].dt.month
#        a["jlcDay"] = a["jlcDateInv"].dt.day
        b = a.groupby(["jlcYear","jlcMonth"],as_index=False).count()
        for yr in range(b["jlcYear"].min(),b["jlcYear"].max()+1):
            stats[yr] = {}
            monthLast = 12
            if yr == pd.Timestamp.today().year:
                monthLast = pd.Timestamp.today().month
            for mo in range(1,monthLast+1):
                stats[yr][mo]=0

        for indx,row in b.iterrows():
            yr = row["jlcYear"]
            mo = row["jlcMonth"]
   #         dy = row["jlcDay"]
            cnt = row[colDate]
            stats[yr][mo]=cnt

        nrec=0
        
        for yr in range(b["jlcYear"].min(),b["jlcYear"].max()+1):
                monthLast = 12
                if yr == pd.Timestamp.today().year:
                    monthLast = pd.Timestamp.today().month
    #        for mo in range(1,monthLast+1):
     #           lu = {f"{mons[mo]}":[stats[yr][mo] }
   #             lu = {f"{mons[mo]}":[stats[yr][mo] for mo in range(1,monthLast)]}
                lu = {f"{mons[nn]}":[stats[yr][nn]] for nn in range(1,monthLast)}
    
                l = {"year":[yr]}

                l.update(lu)
                tmp = pd.DataFrame(l)
                nrec+=1
                if nrec > 1:
                   inv = pd.concat([inv,tmp])
                else:
                   inv = tmp
    
    return inv

