def checkDS(dataset_info,id):
    dct = dataset_info.json()
    stats={}
    
    stats[id]={}
    stats[id]["title"] = dct["name"]
    
    for cols in dct["columns"]:
        column = cols["fieldName"]
        total_rec = requests.get('https://data.colorado.gov/resource/%s?$$app_token=%s&$select=count(*)' % (id4x4, app_token))
        total_rec_count = int(total_rec.json()[0]["count"])
        col_count = requests.get('https://data.colorado.gov/resource/%s?$$app_token=%s&$select=count(%s)' % (id4x4, app_token, column))
        total_col_count = int(col_count.json()[0][f"count_{column}"])
        if total_rec_count > 0:
            pp = total_col_count/total_rec_count*100
        else:
            pp = -1
        
       
        stats[id]["columns"]={}
        stats[id]["columns"][column]={}
        
        stats[id]["columns"][column]["total recs"] = total_rec_count
        stats[id]["columns"][column]["col recs"] = total_col_count
        stats[id]["columns"][column]["% coverage"] = pp
    return stats
        
 #      print(column,total_rec_count,total_col_count,pp)
