def mapIndustry(row):
    nc = row["naics"]
    year = row["year"]
    name=""
    if nc == "------":
       nc = "ALL Industries"
    else:
       nc = nc.replace("/","")
       nc = nc.replace("-","")   
    
    if year  < 2002:
       if nc in naics2002:
          name=naics2002[nc]
    elif year  < 2007:
       if nc in naics2007:
          name=naics2007[nc]
    elif year < 2012:
       if nc in naics2012:
          name=naics2012[nc]
    elif year < 2017:
       if nc in naics2017:
          name=naics2017[nc]
    elif year <= 2023:
       if nc in naics2022:
          name=naics2022[nc]
    if len(name) < 2:
        print(year,nc,name)
   
    
