def getInfo(tmp,what):        
    ftpFile=""
    sij=""
    if (what == "ftp"):
        if "options" in tmp["extract"]:
            for ff in tmp["extract"]["options"]:

                if ff[:2] == "-f":
                    ftpFile=ff[2:]
    elif (what == "sij"):
        if "load" in tmp and "file" in tmp["load"]:
            sij =  tmp["load"]["file"]
    return ftpFile,sij
