def missingAnal(df,sort_by=1):
#  sort_by    1 = sort by % missing file, descending order
#             2 = sort by COlumn Nem
    nrows = df.shape[0]
    stats = pd.DataFrame(columns=["Column","# missing","% missing","Type"])
    print("Total Rows: ",nrows)
    print(f"{'Column':30.30s}   missing   %-miss   Type")
    print(f"-------------------------------------------------------------")
    for col in sorted(df.columns):
        nc = df[col].isna().sum()
        pp = df[col].isna().sum()/nrows*100
#        print(f"{col:30.30s}  {nc:8d}   %{pp:4.1f}   {df[col].dtype}")
        stats = stats.append(pd.DataFrame({"Column":[col],"# missing":nc,"% missing":pp,"Type":[df[col].dtype]}),ignore_index=True)
    sb = "% missing"
    asc=False
    if sort_by == 2:
        sb = "Column"
        asc=True
    stats.sort_values(by=sb,inplace=True,ascending=asc)
    display(stats)
        
missingAnal(regFinanConv)
