    regex["-"] = "-"
    regex["#"] = "#" 
    regex["missing"] = "isna()" 


    stats,nstats = dfStringAnal(df)
    print(nstats)
    header_list = ["Column","digits","non-digits","word","non-word","white-spc","  _  ","  -  ","  #  ","missing"]
    col_widths = [10]*len(header_list)
    col_widths[0] = 25
    print(col_widths)
    statsVals=[]
    for col in sorted(stats.keys()):
         vals=[]
         vals.append(col)
         for k in header_list[1:]:
            vals.append(stats[col][k.strip()])
         statsVals.append(vals)
 

    header_nlist = ["Column"]
    for col in nstats.keys():
        header_nlist.append(col)
    nstatsVals=[]
    for col in sorted(nstats.keys()):
         vals=[]
         vals.append(col)
         print("COL ",col)
         for k in header_nlist[1:]:
            print("K ",k)
            vals.append(nstats[col][k])
         nstatsVals.append(vals)
    


    layout = [
             [sg.Text("Column String Analysis")],
             [sg.Button('Quit')],
             [sg.Multiline(default_text="Summary\n",key="-PINFO-",size=[70,5])],
             [sg.Table(values=statsVals, 
                   background_color='#b3f0ff',text_color="black",
                   auto_size_columns=False,enable_events=True,num_rows=30,col_widths=col_widths,
                   justification='center',alternating_row_color='#33d6ff',pad=(20,20),vertical_scroll_only=False,
                   key='-TABLE-', headings = header_list)],
             [sg.Table(values=nstatsVals, 
                   background_color='#b3f0ff',text_color="black",
                   auto_size_columns=False,enable_events=True,num_rows=30,col_widths=col_widths,
                   justification='center',alternating_row_color='#33d6ff',pad=(20,20),vertical_scroll_only=False,
                   key='-TABLEN-', headings = header_nlist)]
       ]
    # Create the Window
    sg.theme('Lightblue')
    window = sg.Window('Output', layout,finalize=True,resizable=True)
    window.TKroot.focus_set()

    #window2.move(window.current_location()[0]+600, window.current_location()[1])
