def analyzeDfGui(dfO,idcol,windowP,file):
    
    df = dfO.copy()
    regex = {}
    regex["digits"] = "\d"
    regex["non-digits"] = "\D"
    regex["numeric"] = "isdecimal()"
    
    regex["word"] = "\w"
    regex["non-word"] = "[^a-zA-Z0-9_ \-]"
    regex["white-spc"] = "\s"  
    regex["_"] = "_"                        
    regex["-"] = "-"
    regex["#"] = "#" 
    regex["missing"] = "isna()" 


    stats,nstats,ndates,colsNoDate = dfStringAnal(df)

    header_list = ["Column","digits","non-digits","numeric","word","non-word","white-spc","  _  ","  -  ","  #  ","missing","string","integer","float"]
    col_widths = [8]*len(header_list)
    col_widths[0] = 25

    statsVals=[]
    for col in sorted(stats.keys()):
         vals=[]
         vals.append(col)
         for k in header_list[1:]:
            vals.append(stats[col][k.strip()])
         statsVals.append(vals)
    slen= len(statsVals)
    
## Number Stats for Tables
    header_nlist = ["Column","Min","Max","Mean","Std","Missing"]
