import PySimpleGUI as sg
import time
import threading


def long_function_thread():
    time.sleep(10)
#    window.write_event_value('-THREAD DONE-', '')
    layout = [[sg.Output(size=(60,10))],
              [sg.Text("This is a test")]
              [sg.Button('Exit')]  
             ]

    window2 = sg.Window('Window Title', layout,finalize=True)
    while True:             # Event Loop
        event, values = window2.read()
        if event == sg.WIN_CLOSED or event == 'Exit':
            break
        
    window2.close()    

def long_function():
    threading.Thread(target=long_function_thread, daemon=True).start()

def main():
    layout = [[sg.Output(size=(60,10))],
              [sg.Button('Go'), sg.Button('Nothing'), sg.Button('Exit')]  ]

    window = sg.Window('Window Title', layout,finalize=True)

    while True:             # Event Loop
        event, values = window.read()
        if event == sg.WIN_CLOSED or event == 'Exit':
            break
        if event == 'Go':
            print('About to go to call my long function')
            long_function()
            print('Long function has returned from starting')
        elif event == '-THREAD DONE-':
            print('Your long operation completed')
        else:
            print(event, values)
    window.close()
    
if __name__ == '__main__':
    main()
