def analyzeDfGui(dfO,idcol,windowP,file):
    
    df = dfO.copy()
    regex = {}
    regex["digits"] = "\d"
    regex["non-digits"] = "\D"
    regex["numeric"] = "isdecimal()"
    
    regex["word"] = "\w"
    regex["non-word"] = "[^a-zA-Z0-9_ \-]"
    regex["white-spc"] = "\s"  
    regex["_"] = "_"                        
    regex["-"] = "-"
    regex["#"] = "#" 
    regex["missing"] = "isna()" 


    stats,nstats,ndates,colsNoDate = dfStringAnal(df)

    header_list = ["Column","digits","non-digits","numeric","word","non-word","white-spc","  _  ","  -  ","  #  ","missing"]
    col_widths = [8]*len(header_list)
    col_widths[0] = 25

    statsVals=[]
    for col in sorted(stats.keys()):
         vals=[]
         vals.append(col)
         for k in header_list[1:]:
            vals.append(stats[col][k.strip()])
         statsVals.append(vals)
    slen= len(statsVals)
    
## Number Stats for Tables
    header_nlist = ["Column","Min","Max","Mean","Std","Missing"]
    nstatsVals=[]
    for col in sorted(nstats.keys()):
         vals=[]
         vals.append(col)
         for k in header_nlist[1:]:
            vals.append(nstats[col][k])
         nstatsVals.append(vals)
    nlen=len(nstatsVals)

## Date Stats for Tables   
    header_dlist = ["Column","Start","End","# Unique Dates"]
    ndateVals=[]
    for col in sorted(ndates.keys()):
         vals=[]
         vals.append(col)
         for k in header_dlist[1:]:
            vals.append(ndates[col][k])
         ndateVals.append(vals)
    
    
    
    
    layout = [ 
             [sg.Text(f"File: {file}")],
             [sg.Button('Quit')],
             [sg.Multiline(default_text="Summary\n",key="-PINFO-",size=[70,5])],
             [sg.Table(values=statsVals, background_color='#b3f0ff', text_color="black", auto_size_columns=False,enable_events=True,num_rows=slen+2,col_widths=col_widths,font="CENTAUR 15",
                   justification='center',alternating_row_color='#33d6ff',pad=(5,5),vertical_scroll_only=False,
                   key='-TABLE-', headings = header_list)],
             [sg.Table(values=nstatsVals, 
                   background_color='#b3f0ff',text_color="black",
                   auto_size_columns=False,enable_events=True,num_rows=nlen+2,col_widths=col_widths,font="CENTAUR 15",justification='center',alternating_row_color='#33d6ff',pad=(5,5),vertical_scroll_only=False,
                   key='-TABLEN-', headings = header_nlist)],
             [sg.Text("Convert Column to Date",font="CENTAUR 15"),sg.Combo(colsNoDate,s=[25,4],font="CENTAUR 15 bold",expand_y=True,key="-CONVDATE-",enable_events=True),sg.Text("Format: "),sg.Multiline("",s=(10,1),key="-DATEFORM-"),sg.Button("Convert to Date")],
             [sg.Table(values=ndateVals, 
                   background_color='#b3f0ff',text_color="black",
                   auto_size_columns=False,enable_events=True,num_rows=nlen+2,col_widths=[25,12,12,10],font="CENTAUR 15",justification='center',alternating_row_color='#33d6ff',pad=(5,5),vertical_scroll_only=False,
                   key='-TABLED-', headings = header_dlist)]
       ]
    # Create the Window
    sg.theme('Lightblue')
    window = sg.Window('Output', layout,finalize=True,resizable=True)
    window.TKroot.focus_set()

    #window2.move(window.current_location()[0]+600, window.current_location()[1])
