             [sg.Table(values=statsVals, background_color='#b3f0ff', text_color="black", auto_size_columns=False,enable_events=True,num_rows=20,col_widths=col_widths,font="CENTAUR 10",
                   justification='center',alternating_row_color='#33d6ff',pad=(5,5),vertical_scroll_only=False,
                   key='-TABLE-', headings = header_list)],
             [sg.Table(values=nstatsVals, 
                   background_color='#b3f0ff',text_color="black",
                   auto_size_columns=False,enable_events=True,num_rows=15,col_widths=col_widths,font="CENTAUR 10",justification='center',alternating_row_color='#33d6ff',pad=(5,5),vertical_scroll_only=False,
                   key='-TABLEN-', headings = header_nlist)],
