    regex["word"] = "\w"
    regex["non-word"] = "[^a-zA-Z0-9_ \-]"
    regex["white-spc"] = "\s"  
    regex["_"] = "_"                        
    regex["-"] = "-"
    regex["#"] = "#" 
    regex["missing"] = "isna()" 
    regex["integer"] = "isinstance(x,int)" 
    
    nrs,ncs = df.shape

    stats,nstats,ndates,colsNoDate = dfStringAnal(df,windowP)
    columnSortStateTable = {}
    columnSortStateTableN = {}
