def setRowColors(dct,col1,col2,colsp):
    count=0
    colors = {}
    for key in dct.keys():
        if count%2 == 0:
            colors[key] = col1
        else:
            colors[key] = col2
        if dct[key]["% miss"] > 99.0:
            colors[key] = colsp
        count+=1
        
    return colors

